import re,json
from pathlib import Path
P=Path(__file__).resolve().parent
items=json.loads((P/'c_items.json').read_text())
keys={k for x in items for k in x['refs']}
entries={}
for path in [P.parent/'references_cumulative.bib',P/'b_references.bib',P/'root_references.bib']:
    t=path.read_text()
    for m in re.finditer(r'@\w+\{([^,]+),',t):
        k=m[1]
        if k not in keys or k in entries:continue
        i=m.end();d=1
        while d:
            if t[i]=='{':d+=1
            if t[i]=='}':d-=1
            i+=1
        entries[k]=t[m.start():i]

def add(key,author,title,year,url,annote,**fields):
    typ=fields.pop('typ','article');note=fields.pop('note','verified')
    data=dict(author=author,title=title,year=str(year),**fields,url=url,note=note,annote=annote)
    entries[key]='@'+typ+'{'+key+',\n'+',\n'.join('  '+k+' = {'+v+'}' for k,v in data.items())+'\n}'

